/**
 * A perna da gaivota — porte de `componentes/viz/gaivota.js`.
 *
 * A gaivota fica horas de pé no gelo e não perde o corpo de frio. O truque é um
 * trocador de calor em CONTRACORRENTE: a artéria que desce quente e a veia que
 * sobe fria correm coladas, e o calor passa de uma para a outra ao longo de todo
 * o trajeto. O sangue chega ao pé já frio — pouco calor a perder — e volta ao
 * corpo já reaquecido.
 *
 * Se os dois fluxos vão na MESMA direção, eles se emparelham na temperatura
 * morna no meio do caminho e a troca para ali. É o mesmo comprimento de contato,
 * e metade do resultado — o sentido é que decide.
 *
 * **A cena virou 2D.** No legado era 3D, mas os dois vasos ficavam num plano só,
 * vistos de frente: um diagrama de trocador de calor com uma câmera em volta.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  etiqueta,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const SEGMENTOS = 22;
const HEMACIAS = 12;
const SETAS = 9;

/** Azul-frio → âmbar → vermelho-quente. Fora da fábrica: a `ave` também usa. */
function corDaTemperatura(temp: number, tGelo: number, tCorpo: number): string {
  const f = limitar((temp - tGelo) / Math.max(1e-6, tCorpo - tGelo), 0, 1);
  const canal = (v: number): number => Math.round(limitar(v, 0, 1) * 255);

  return f < 0.5
    ? `rgb(${canal(0.23 + f * 1.1)} ${canal(0.55 + f * 0.7)} ${canal(1 - f * 0.5)})`
    : `rgb(255 ${canal(0.9 - (f - 0.5) * 1.2)} ${canal(0.5 - (f - 0.5) * 0.9)})`;
}

/**
 * A gaivota de perfil, em pé sobre o gelo.
 *
 * O que estava aqui era uma elipse branca vazia rotulada "corpo": nada dizia
 * que o assunto era um bicho, e menos ainda que a perna dele é o trocador
 * desenhado ao lado. Agora ela tem manto cinza, ponta de asa preta, o bico
 * amarelo com a mancha vermelha da gaivota-argêntea e a perna cor de laranja —
 * e é a perna que amarra a figura ao gráfico.
 *
 * As duas pernas ficam: uma recolhida contra o corpo (é assim que ela reduz a
 * perda de calor) e uma no chão, que é a que o trocador descreve.
 */
function ave(
  ctx: CanvasRenderingContext2D,
  cx: number,
  chao: number,
  tamanho: number,
  tCorpo: number,
  tGelo: number,
  t: number,
): void {
  const cor = paleta();
  const alturaPerna = tamanho * 0.55;
  const corpoY = chao - alturaPerna - tamanho * 0.5;

  // A perna de apoio: quente em cima, fria embaixo — o gradiente é a lição.
  const perna = ctx.createLinearGradient(0, corpoY + tamanho * 0.35, 0, chao);
  perna.addColorStop(0, corDaTemperatura(tCorpo, tGelo, tCorpo));
  perna.addColorStop(1, corDaTemperatura(tGelo + 1, tGelo, tCorpo));
  ctx.strokeStyle = perna;
  ctx.lineWidth = Math.max(3, tamanho * 0.09);
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(cx + tamanho * 0.05, corpoY + tamanho * 0.35);
  ctx.lineTo(cx + tamanho * 0.05, chao);
  ctx.stroke();

  // O pé palmado.
  ctx.fillStyle = '#e8a04a';
  ctx.beginPath();
  ctx.moveTo(cx - tamanho * 0.12, chao);
  ctx.lineTo(cx + tamanho * 0.3, chao);
  ctx.lineTo(cx + tamanho * 0.05, chao - tamanho * 0.06);
  ctx.closePath();
  ctx.fill();

  // A outra perna, recolhida junto ao corpo.
  ctx.strokeStyle = '#e8a04a';
  ctx.lineWidth = Math.max(2.4, tamanho * 0.07);
  ctx.beginPath();
  ctx.moveTo(cx - tamanho * 0.12, corpoY + tamanho * 0.38);
  ctx.lineTo(cx - tamanho * 0.3, corpoY + tamanho * 0.5);
  ctx.stroke();

  // A cauda, atrás.
  ctx.fillStyle = '#e9edf4';
  ctx.beginPath();
  ctx.moveTo(cx - tamanho * 0.35, corpoY);
  ctx.lineTo(cx - tamanho * 0.88, corpoY - tamanho * 0.14);
  ctx.lineTo(cx - tamanho * 0.82, corpoY + tamanho * 0.14);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#2b3140';
  ctx.beginPath();
  ctx.moveTo(cx - tamanho * 0.72, corpoY - tamanho * 0.12);
  ctx.lineTo(cx - tamanho * 0.88, corpoY - tamanho * 0.14);
  ctx.lineTo(cx - tamanho * 0.83, corpoY + tamanho * 0.13);
  ctx.closePath();
  ctx.fill();

  // O corpo.
  ctx.fillStyle = '#f4f7fb';
  ctx.strokeStyle = cor.trilho;
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.ellipse(cx, corpoY, tamanho * 0.62, tamanho * 0.42, -0.12, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();

  // O manto cinza, a asa dobrada — respira devagar, para a ave não ficar morta.
  const respira = Math.sin(t * 1.6) * tamanho * 0.015;
  ctx.fillStyle = '#b9c4d2';
  ctx.beginPath();
  ctx.ellipse(
    cx - tamanho * 0.08,
    corpoY - tamanho * 0.04 + respira,
    tamanho * 0.5,
    tamanho * 0.24,
    -0.18,
    0,
    Math.PI * 2,
  );
  ctx.fill();
  ctx.fillStyle = '#2b3140';
  ctx.beginPath();
  ctx.ellipse(
    cx - tamanho * 0.45,
    corpoY + tamanho * 0.02 + respira,
    tamanho * 0.16,
    tamanho * 0.09,
    -0.3,
    0,
    Math.PI * 2,
  );
  ctx.fill();

  // O pescoço e a cabeça.
  ctx.fillStyle = '#f4f7fb';
  ctx.beginPath();
  ctx.moveTo(cx + tamanho * 0.3, corpoY - tamanho * 0.25);
  ctx.quadraticCurveTo(
    cx + tamanho * 0.6,
    corpoY - tamanho * 0.6,
    cx + tamanho * 0.58,
    corpoY - tamanho * 0.85,
  );
  ctx.lineTo(cx + tamanho * 0.3, corpoY - tamanho * 0.8);
  ctx.quadraticCurveTo(
    cx + tamanho * 0.35,
    corpoY - tamanho * 0.5,
    cx + tamanho * 0.12,
    corpoY - tamanho * 0.28,
  );
  ctx.closePath();
  ctx.fill();

  const cabecaX = cx + tamanho * 0.52;
  const cabecaY = corpoY - tamanho * 0.88;
  ctx.beginPath();
  ctx.arc(cabecaX, cabecaY, tamanho * 0.24, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();

  // O bico amarelo, com a mancha vermelha na mandíbula.
  ctx.fillStyle = '#e8c04a';
  ctx.beginPath();
  ctx.moveTo(cabecaX + tamanho * 0.15, cabecaY - tamanho * 0.06);
  ctx.lineTo(cabecaX + tamanho * 0.62, cabecaY + tamanho * 0.02);
  ctx.lineTo(cabecaX + tamanho * 0.15, cabecaY + tamanho * 0.12);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#d2402f';
  ctx.beginPath();
  ctx.arc(cabecaX + tamanho * 0.42, cabecaY + tamanho * 0.06, tamanho * 0.045, 0, Math.PI * 2);
  ctx.fill();

  // O olho.
  ctx.fillStyle = cor.texto;
  ctx.beginPath();
  ctx.arc(cabecaX + tamanho * 0.06, cabecaY - tamanho * 0.05, tamanho * 0.055, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = 'rgb(255 255 255 / 80%)';
  ctx.beginPath();
  ctx.arc(cabecaX + tamanho * 0.04, cabecaY - tamanho * 0.07, tamanho * 0.02, 0, Math.PI * 2);
  ctx.fill();
}

const gaivota: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /**
   * A temperatura dos dois vasos em `u` (0 no corpo, 1 no pé). O contato ocupa a
   * fração central `contato`; fora dele não há troca.
   */
  function perfil(
    u: number,
    oposto: boolean,
    eficiencia: number,
    tCorpo: number,
    tGelo: number,
    contato: number,
  ): readonly [number, number] {
    const c0 = 0.5 - contato / 2;
    const c1 = 0.5 + contato / 2;
    const faixa = tCorpo - tGelo;
    const tPe = tCorpo - eficiencia * faixa;
    const tRetorno = tGelo + eficiencia * faixa;

    const w = contato <= 0 ? (u < 0.5 ? 0 : 1) : limitar((u - c0) / (c1 - c0), 0, 1);

    const arteria = tCorpo - (tCorpo - tPe) * w;
    // Em contracorrente a veia sobe: fria embaixo, quente ao chegar ao corpo. Na
    // mesma direção, os dois descem juntos e a veia volta fria.
    const veia = oposto ? tGelo + (tRetorno - tGelo) * (1 - w) : tGelo + (tRetorno - tGelo) * w;

    return [arteria, veia];
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);

    const oposto = info.oposto === true;
    const eficiencia = numeroDe(info, 'efic', 0);
    const tCorpo = numeroDe(info, 'tCorpo', 41);
    const tGelo = numeroDe(info, 'tGelo', 4);
    const contato = limitar(numeroDe(info, 'L', 0) / 100, 0, 1);
    const ok = info.ok === true;

    titulo(ctx, L, A, oposto ? 'Contracorrente' : 'Mesma direção');

    // A ave à esquerda, o trocador à direita: o quadro deixou de ser uma coluna
    // estreita e passou a usar a largura, que é onde havia espaço.
    const topo = A * 0.26;
    const base = A * 0.76;
    const altura = base - topo;
    const cx = L * 0.66;
    const meia = limitar(L * 0.06, 14, 30);
    const xArteria = cx - meia;
    const xVeia = cx + meia;
    const largura = limitar(meia * 0.5, 8, 16);

    // O gelo: uma placa só, atravessando a cena inteira, com a ave em pé nela.
    const yGelo = base + A * 0.07;
    retangulo(ctx, L * 0.03, yGelo, L * 0.94, A * 0.075, 4, '#bfe6ff', cor.trilho, 1);
    ctx.strokeStyle = '#8fbfd8';
    ctx.lineWidth = 1;
    for (const u of [0.2, 0.45, 0.72]) {
      ctx.beginPath();
      ctx.moveTo(L * (0.03 + u * 0.94), yGelo);
      ctx.lineTo(L * (0.03 + u * 0.94) + 8, yGelo + A * 0.075);
      ctx.stroke();
    }

    // A gaivota, e a perna dela que desce até o gelo — é ela que o trocador de
    // calor ao lado está detalhando.
    ave(ctx, L * 0.24, yGelo, Math.min(L * 0.15, A * 0.19), tCorpo, tGelo, t);

    // O corpo, no alto do trocador: a fonte quente de onde o sangue desce.
    retangulo(
      ctx,
      cx - L * 0.16,
      topo - A * 0.1,
      L * 0.32,
      A * 0.07,
      A * 0.035,
      '#f6dcd6',
      cor.trilho,
      1.4,
    );

    // Os dois vasos, faixa a faixa, cada uma na cor da sua temperatura.
    const segH = altura / SEGMENTOS;
    let tRetorno = tGelo;
    for (let i = 0; i < SEGMENTOS; i++) {
      const u = (i + 0.5) / SEGMENTOS;
      const [ta, tv] = perfil(u, oposto, eficiencia, tCorpo, tGelo, contato);
      const y = topo + i * segH;

      ctx.fillStyle = corDaTemperatura(ta, tGelo, tCorpo);
      ctx.fillRect(xArteria - largura / 2, y, largura, segH + 0.5);

      ctx.fillStyle = corDaTemperatura(tv, tGelo, tCorpo);
      ctx.fillRect(xVeia - largura / 2, y, largura, segH + 0.5);

      if (i === 0) tRetorno = tv;
    }

    // As setas de calor, só na faixa de contato — é o que se está regulando.
    const c0 = 0.5 - contato / 2;
    if (contato > 0.02) {
      for (let i = 0; i < SETAS; i++) {
        const u = c0 + (contato * (i + 0.5)) / SETAS;
        const y = topo + u * altura;
        const pulso = 0.5 + 0.5 * Math.sin(t * 3 - i * 0.6);

        ctx.globalAlpha = (0.15 + 0.85 * eficiencia) * pulso;
        ctx.fillStyle = cor.ouro;
        ctx.beginPath();
        ctx.moveTo(xArteria + largura * 0.6, y);
        ctx.lineTo(xVeia - largura * 0.6, y);
        ctx.lineTo(xVeia - largura * 0.6 - 6, y - 4);
        ctx.moveTo(xVeia - largura * 0.6, y);
        ctx.lineTo(xVeia - largura * 0.6 - 6, y + 4);
        ctx.strokeStyle = cor.ouro;
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.globalAlpha = 1;
      }
    }

    // As hemácias correndo. Na artéria sempre descem; na veia, sobem ou descem —
    // e é aí que se vê o sentido do fluxo.
    for (let i = 0; i < HEMACIAS; i++) {
      const pa = (i / HEMACIAS + t * 0.12) % 1;
      ctx.fillStyle = '#d2402f';
      ctx.beginPath();
      ctx.arc(xArteria, topo + pa * altura, largura * 0.28, 0, Math.PI * 2);
      ctx.fill();

      const bruto = i / HEMACIAS + t * 0.12;
      const pv = oposto ? 1 - (bruto % 1) : bruto % 1;
      ctx.fillStyle = '#3a7fd2';
      ctx.beginPath();
      ctx.arc(xVeia, topo + pv * altura, largura * 0.28, 0, Math.PI * 2);
      ctx.fill();
    }

    const miudo = limitar(A * 0.036, 9, 12);
    texto(ctx, `corpo · ${Math.round(tCorpo)} °C`, cx, topo - A * 0.065, miudo, {
      cor: cor.texto,
      peso: 700,
    });
    texto(ctx, `gelo · ${Math.round(tGelo)} °C`, L * 0.24, yGelo + A * 0.045, miudo, {
      cor: cor.azul,
      peso: 700,
    });
    texto(ctx, 'artéria', xArteria, base + A * 0.032, miudo * 0.9, { cor: cor.fraco });
    texto(ctx, 'veia', xVeia, base + A * 0.032, miudo * 0.9, { cor: cor.fraco });

    // O número que decide: a que temperatura o sangue volta ao corpo.
    etiqueta(
      ctx,
      `volta a ${tRetorno.toFixed(1).replace('.', ',')} °C`,
      L * 0.24,
      A * 0.28,
      limitar(A * 0.042, 10, 14),
      ok ? cor.verde : cor.texto,
      800,
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default gaivota;
